<?php require_once __DIR__.'/includes/auth.php'; if(current_user()) redirect(current_user()['role'].'/dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$s=$pdo->prepare('SELECT id,full_name,email,password_hash,role,is_active FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&$u['is_active']&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'full_name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']];redirect($u['role'].'/dashboard.php');}$error='Incorrect email or password, or the account is inactive.';}
$pageTitle='Log in';require __DIR__.'/includes/header.php';?><section class="form-wrap"><h1>Welcome back</h1><p>Log in to manage reports and claims.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Email address<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary" type="submit">Log in</button></form><p>New to CampusFind? <a href="<?=e(url('register.php'))?>">Create an account</a></p></section><?php require __DIR__.'/includes/footer.php';?>
